args.command:
# run-all.sh attached a blank 1 GiB disk; it becomes X: for a push to another volume than %SystemRoot%\Temp.
if (-not (Get-Partition -DriveLetter X -ErrorAction SilentlyContinue)) {
  $disk = @(Get-Disk | Where-Object { $_.Size -eq 1GB -and $_.Number -ne 0 })
  if ($disk.Count -ne 1) { "found $($disk.Count) 1 GiB disks"; exit 1 }
  if ($disk[0].PartitionStyle -eq 'RAW') { $disk[0] | Initialize-Disk -PartitionStyle GPT }
  New-Partition -DiskNumber $disk[0].Number -UseMaximumSize -DriveLetter X | Format-Volume -FileSystem NTFS -Confirm:$false | Out-Null
}
[void](New-Item -ItemType Directory -Force 'X:\vmm-vol')
icacls X:\vmm-vol /inheritance:r /grant:r '*S-1-5-32-545:(OI)(CI)F' '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null
'ready ' + (Get-Volume -DriveLetter X).FileSystem

$t = 'X:\vmm-vol\app'
Get-ChildItem -LiteralPath $t -Recurse -File -Force | Sort-Object FullName | ForEach-Object { $_.FullName.Substring($t.Length + 1) + ' ' + (Get-FileHash -LiteralPath $_.FullName).Hash }
function Rules($d) { foreach ($r in '', '\a.txt', '\sub', '\sub\b.txt') { $a = Get-Acl -LiteralPath "$d$r"; "$r protected=$($a.AreAccessRulesProtected)"; $a.Access | ForEach-Object { "$r $($_.IdentityReference) $($_.FileSystemRights) $($_.InheritanceFlags) $($_.PropagationFlags) inherited=$($_.IsInherited)" } } }
$ref = 'X:\vmm-vol\ref'
[void](New-Item -ItemType Directory "$ref\sub")
Set-Content -LiteralPath "$ref\a.txt" -Value a
Set-Content -LiteralPath "$ref\sub\b.txt" -Value b
if (Compare-Object (Rules $t) (Rules $ref)) { 'acl=differs'; Rules $t; '--'; Rules $ref } else { 'acl=same' }
'vmm=' + (Get-ChildItem -Force -LiteralPath 'X:\vmm-vol', (Join-Path $env:SystemRoot 'Temp') -Filter '.vmm-*' | Measure-Object).Count
# A push on the system volume moves the unpacked tree, so its times are the ones tar.exe set; the copy must keep them.
$c = 'C:\vmm-volref\app'
$times = Get-ChildItem -LiteralPath $t -Recurse -Force | ForEach-Object { $r = $_.FullName.Substring($t.Length); $o = Get-Item -LiteralPath "$c$r" -Force; if ($_ -is [IO.FileInfo] -and $_.LastWriteTimeUtc -ne $o.LastWriteTimeUtc) { "$r $($_.LastWriteTimeUtc.Ticks) $($o.LastWriteTimeUtc.Ticks)" } }
if ($times) { 'times=differ'; $times } else { 'times=same' }
Remove-Item -LiteralPath 'C:\vmm-volref' -Recurse -Force
